const raw = $json.content?.[0]?.text || '';

let parsed;
try {
  const clean = raw.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(clean);
} catch(e) { return []; }

if (!parsed.is_job) return [];

